func (r *queryResolver) GetProductURL(ctx context.Context, productID string) ([]*string, error) {
	var product model.Product
	if err := r.DB.Where("id = ?", productID).Find(&product).Error; err != nil {
		return nil, err
	}
	var ImageUrls []*string
	for _, v := range product.ImageUrls {
		// Fetch the image data from MinIO
		imageData, err := helper.ImageFromMinIOURL(ctx, r.MinIOClient, v)
		if err != nil {
			return nil, fmt.Errorf("error retrieving image data from MinIO: %w", err)
		}

		// Convert the image data to a base64 string and add it to the list
		base64Image := base64.StdEncoding.EncodeToString(imageData)
		ImageUrls = append(ImageUrls, &base64Image)

	}
	return ImageUrls, nil
}
